window.docContents[31].resolve({"/Logic/#Logical-Foundations--Logic-in-Lean--The-Logic-of-Lean":{"contents":"Lean's logical core differs in some important ways from other formal\nsystems that are used by mathematicians to write down precise and rigorous\ndefinitions and proofs – in particular from Zermelo–Fraenkel Set Theory\n(ZFC), the most popular foundation for paper-and-pencil mathematics.We conclude this chapter with a brief discussion of some of the\nmost significant differences between these two worlds.\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Logic in Lean","header":"8.8. The Logic of Lean","id":"/Logic/#Logical-Foundations--Logic-in-Lean--The-Logic-of-Lean"}});